namespace SpriteKind {
    export let Title = SpriteKind.create()
    export let Herbivore = SpriteKind.create()
    export let Carnivore = SpriteKind.create()
}

// project initialization
let dinoArray = [assets.image`dino0`, assets.image`dino1`, assets.image`dino2`, assets.image`dino3`]
let gameStart = false
let dinoCount = 0
let spriteDirection = "right"

let mySprite: Sprite = null
let dinosaur: Sprite = null

function createIntroText() {
    let introText0 = textsprite.create("Feed the", 0, 5)
    introText0.setMaxFontHeight(16)
    introText0.setPosition(screen.width / 2, 25)
    introText0.setKind(SpriteKind.Title)
    let introText1 = textsprite.create("hungry dinos!", 0, 5)
    introText1.setMaxFontHeight(16)
    introText1.setPosition(screen.width / 2, 40)
    introText1.setKind(SpriteKind.Title)
    let introText2 = textsprite.create("Press A", 0, 1)
    introText2.setPosition(screen.width / 2, 60)
    introText2.setKind(SpriteKind.Title)
    let introText3 = textsprite.create("to feed the herbivores.", 0, 1)
    introText3.setPosition(screen.width / 2, 70)
    introText3.setKind(SpriteKind.Title)
    let introText4 = textsprite.create("Press B", 0, 1)
    introText4.setPosition(screen.width / 2, 90)
    introText4.setKind(SpriteKind.Title)
    let introText5 = textsprite.create("to feed the carnivores.", 0, 1)
    introText5.setPosition(screen.width / 2, 100)
    introText5.setKind(SpriteKind.Title)
    sprites.destroyAllSpritesOfKind(SpriteKind.Title)
    gameStart = true
    callScene(2)
}

function createDinos() {
    for (let location of tiles.getTilesByType(assets.tile`spawnTile`)) {
        if (Math.percentChance(60)) {
            dinosaur = sprites.create(dinoArray[randint(0, 2)], SpriteKind.Herbivore)
        } else {
            dinosaur = sprites.create(dinoArray[3], SpriteKind.Carnivore)
        }
        tiles.placeOnTile(dinosaur, location)
        tiles.setTileAt(location, assets.tile`coverTile`)
        dinosaur.setScale(randint(1, 1.5))
        animation.runMovementAnimation(dinosaur, animation.animationPresets(animation.shake), randint(3000, 6000), true)
    }
}

function sendFood(image: Image) {
    if (gameStart) {
        let projectile = sprites.createProjectileFromSprite(image, mySprite, 0, 0)
        if (spriteDirection == "right") {
            projectile.vx = 80
        } else if (spriteDirection == "left") {
            projectile.vx = -80
        }
    }
}

function dinoFull(sprite: Sprite) {
    sprite.setFlag(SpriteFlag.GhostThroughSprites, true)
    dinoCount += 1
    sprite.startEffect(effects.smiles)
}

function callScene(sceneNum: number) {
    if (sceneNum == 0) { // splash screen
        let backgroundScreen = sprites.create(assets.image`titleScreen`, SpriteKind.Title)
        let textScreen= sprites.create(assets.image`titleText`, SpriteKind.Title)
        controller.pauseUntilAnyButtonIsPressed()
        sprites.destroy(textScreen)
        callScene(1)
    } else if (sceneNum == 1) { // intro screen
        createIntroText()
    } else if (sceneNum == 2) { // game
        tiles.setCurrentTilemap(tilemap`level`)
        mySprite = sprites.create(assets.image`playerRight`, SpriteKind.Player)
        mySprite.x = 20
        controller.moveSprite(mySprite, 70, 70)
        scene.cameraFollowSprite(mySprite)
        createDinos()
    }
}

// game start
callScene(0)

// game events
controller.right.onEvent(ControllerButtonEvent.Pressed, function () {
    if (gameStart) {
        mySprite.setImage(assets.image`playerRight`)
        spriteDirection = "right"
    }
})

controller.left.onEvent(ControllerButtonEvent.Pressed, function () {
    if (gameStart) {
        mySprite.setImage(assets.image`playerLeft`)
        spriteDirection = "left"
    }
})

controller.A.onEvent(ControllerButtonEvent.Pressed, function () {
    sendFood(assets.image`leafImage`)
})

controller.B.onEvent(ControllerButtonEvent.Pressed, function () {
    sendFood(assets.image`meatImage`)
})

sprites.onOverlap(SpriteKind.Projectile, SpriteKind.Herbivore, function (sprite, otherSprite) {
    if (sprite.image.equals(assets.image`leafImage`)) {
        sprites.destroy(sprite)
    }
})

sprites.onOverlap(SpriteKind.Projectile, SpriteKind.Carnivore, function (sprite, otherSprite) {
    if (sprite.image.equals(assets.image`meatImage`)) {
        sprites.destroy(sprite)
    }
})
